N = 579
N_N_minus_1 = N * (N - 1)

def check_divisors(target):
    divisors = []
    for d in range(1, int(target**0.5) + 1):
        if target % d == 0:
            divisors.append(d)
            if d * d != target:
                divisors.append(target // d)
    return sorted(divisors)

print(f"N*(N-1) = {N_N_minus_1}")

# We are looking for odd n such that n*(n-1) divides N_N_minus_1
# Since n is odd, n-1 is even.
print("\nChecking specific small odd n:")
for n in [3, 5, 7, 9, 11, 13]:
    n_n_minus_1 = n * (n - 1)
    if N_N_minus_1 % n_n_minus_1 == 0:
        r = N_N_minus_1 // n_n_minus_1
        print(f"n={n}: Divides. r={r}")
    else:
        print(f"n={n}: Does not divide.")
